from pathlib import Path
import json,html
R=Path(__file__).resolve().parents[1];e=html.escape
d=json.loads((R/'content.json').read_text(encoding='utf-8'))
cards=''
for r in d['reels']:
 cards+=f'''<article id="{r['id']}"><video controls playsinline preload="metadata" poster="assets/{r['id']}-poster.jpg" src="assets/{r['id']}.mp4" aria-label="{e(r['title'])}"></video><div><small>NEW · 15 SECONDS · 1080 × 1920</small><h2>{e(r['title'])}</h2><p>Real people in moving footage, a labelled product demo and a short branded ending. Text is baked in. Silent master: add music from the publishing platform’s own library.</p><p><a class="button" href="assets/{r['id']}.mp4" download>Download MP4 ↓</a> <button>Copy caption</button></p><textarea aria-label="Caption for {e(r['title'])}">{e(r['caption'])}</textarea><p class="credit">Footage: <a href="{r['source']}" target="_blank" rel="noopener">{e(r['author'])} / Pexels</a>. Illustrative stock scene; the people shown are not claimed as customers.</p></div></article>'''
old=[('Welcome and house guidance','../respect-host-voice-2026-10-28/assets/video-01-welcome.mp4'),('Memories and private feedback','../respect-host-voice-2026-10-28/assets/video-02-memories-feedback.mp4'),('Your welcome, in your words','../home-2026-11-02/week1-assets/2026-11-04_instagram_reel_your-welcome.mp4')]
earlier=''.join(f'<div><h3>{e(t)}</h3><video controls playsinline preload="none" src="{s}" aria-label="{e(t)}"></video><p><a href="{s}" download>Download MP4 ↓</a></p></div>' for t,s in old)
css='''*{box-sizing:border-box}body{margin:0;background:#f7f2e8;color:#1e2a25;font:16px/1.6 Arial}header,main{max-width:1180px;margin:auto;padding:32px 24px}header{padding-top:45px}header img{width:280px}h1{font:54px/1.1 Georgia;margin:22px 0}h2{font:36px/1.15 Georgia}small{font-size:12px;letter-spacing:2px}header p{max-width:750px}a{color:#984529}nav{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}nav a,.button,button{display:inline-block;border:1px solid #bbae99;border-radius:6px;background:white;padding:9px 15px;text-decoration:none;font:inherit;color:#74321f;cursor:pointer}article{display:grid;grid-template-columns:minmax(0,390px) minmax(0,1fr);gap:40px;margin-bottom:60px;padding-bottom:45px;border-bottom:1px solid #d4c7b2}video{display:block;width:100%;max-height:700px;border-radius:8px;background:#1e2a25}textarea{width:100%;min-height:285px;border:1px solid #c3b7a2;border-radius:6px;padding:15px;font:15px/1.55 Arial;background:#fffdf8;resize:vertical}.credit{font-size:13px;color:#5b625d}.old{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.old video{max-height:430px}.note{background:#e4eade;padding:18px;border-radius:6px}@media(max-width:700px){header,main{padding:26px 18px}h1{font-size:40px}article{grid-template-columns:1fr;gap:20px}h2{font-size:30px}.old{grid-template-columns:1fr}.old video{max-height:560px}}'''
(R/'REVIEW.html').write_text(f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DigiStayBook · Reels with real people</title><style>{css}</style></head><body><header><a href="../../MARKETING_PLAN.html">← Marketing plan</a> · <a href="../people-2026-10-28/REVIEW.html">Photo collection</a><p><img src="reference/logo.png" alt="DigiStayBook"></p><small>REELS / 29 OCTOBER 2026</small><h1>Real people. Moving moments.</h1><p>Two new Reels using genuine moving stock footage, alongside three earlier demo-led videos below. Each new Reel runs for 15 seconds in portrait format.</p><p class="note">Drafts for review. Silent masters with burned-in text; add native licensed music before publishing. No posts or external schedules have changed.</p><nav><a href="DigiStayBook-people-reels.zip" download>Download both Reels ↓</a><a href="CAPTIONS.md">Captions</a><a href="SOURCES.md">Footage credits</a><a href="#earlier">3 earlier videos ↓</a></nav></header><main>{cards}<section id="earlier"><h2>Earlier demo-led Reels</h2><p>These are the three existing edits from the previous packs. They are separate from the two new live-action Reels above.</p><div class="old">{earlier}</div></section></main><script>document.querySelectorAll('article button').forEach(b=>b.onclick=async()=>{{const t=b.closest('article').querySelector('textarea');try{{await navigator.clipboard.writeText(t.value);b.textContent='Copied';setTimeout(()=>b.textContent='Copy caption',1800)}}catch{{t.focus();t.select();b.textContent='Text selected — copy now'}}}});</script></body></html>''',encoding='utf-8')
print('Built review page with two new and three existing Reels.')
